"""Authored Ukrainian course content. Build: python tools/build_chapters.py."""
CHAPTERS = []
def chapter(title, outcome, theory, terms, formula, worked, architecture, pattern, practices, antipatterns, steps, lab, automatic, manual, questions, reading, video):
    CHAPTERS.append(dict(title=title,outcome=outcome,theory=theory,terms=terms,formula=formula,worked=worked,architecture=architecture,pattern=pattern,practices=practices,antipatterns=antipatterns,steps=steps,lab=lab,automatic=automatic,manual=manual,questions=questions,reading=reading,video=video))

chapter('Основи AI Engineering',
'Спроєктувати контракт AI-продукту, відокремити детерміновану логіку від генерації та підготувати baseline, з яким можна порівнювати наступні модулі.',
[
'''AI Engineering починається з поведінки системи, а не з вибору найновішої моделі. Уявімо асистента для внутрішньої документації: користувач хоче знайти інструкцію, зрозуміти її та перевірити джерело. Успіх — правильна, доступна саме цьому користувачеві відповідь із посиланням. Красивий текст без підтвердження не виконує задачу. До написання інтеграції складіть список запитів, очікуваних результатів і ситуацій, коли система має відмовитися. Такий контракт перетворює абстрактне «зробити AI» на перевірювану інженерну роботу.''',
'''Традиційний сервіс за однакових умов зазвичай повертає однаковий результат. Генеративна модель може змінювати формулювання й помилятися навіть на знайомому питанні. Тому надійність створюється навколо моделі: обмеженням входу, перевіркою виходу, доступом до джерел, тайм-аутами та спостереженням. Модель не повинна визначати права доступу, виконувати SQL або вирішувати, чи дозволена фінансова операція. Ці рішення залишаються у детермінованому коді, який можна протестувати незалежно від провайдера.''',
'''Навчальний наскрізний проєкт — асистент із базою знань. На першому тижні він відповідає через fake-провайдер. Пізніше ви додасте вектори, retrieval, генерацію, оцінювання та деплой. Fake потрібен для швидких тестів HTTP-контракту без ключів і витрат, але його результати не доводять якість LLM. Зберігайте окремо технічні тести та експерименти на реальній моделі. Кожна зміна має порівнюватися з попереднім baseline на тих самих питаннях.'''],
[
('Inference','Отримання відповіді вже навченої моделі. Навчання змінює параметри; inference використовує їх. Інтеграція API не означає, що ви тренуєте модель.'),
('Baseline','Найпростіший вимірюваний варіант рішення: ключові слова, шаблонна відповідь або ручний пошук. Складність виправдана лише коли дає вимірювану перевагу.'),
('SLO','Ціль роботи сервісу: наприклад p95 затримки нижче заданого порога. Це обіцянка продукту, а не середнє значення одного успішного запиту.'),
('Failure mode','Спосіб, яким система може зламатися: вигадана цитата, недоступний провайдер, витік чужого документа. Для кожного потрібен контроль і очікувана відповідь.')],
'Очікувана корисність U = P(успіх) × цінність успіху − P(помилка) × збиток − вартість запиту.',
'''Якщо правильна відповідь економить 10 хвилин, а перевірка помилки забирає 30, система з точністю 80% дає 0,8×10 − 0,2×30 = 2 хвилини очікуваної економії до врахування витрат. За точності 60% економія вже від’ємна. Це спрощена модель: помилки різні за тяжкістю, а реальні частоти оцінюються на репрезентативних даних. Вона пояснює, чому відмова за недостатнього контексту може бути кориснішою за впевнену відповідь.''',
['Користувач','HTTP + валідація','Use case','Provider adapter'],
('Ports and adapters','Use case залежить від інтерфейсу generate(), а не від SDK. HTTP-адаптер перетворює запит на вхідні дані; fake та реальний провайдер реалізують один контракт. Так заміна постачальника не змінює бізнес-логіку. Не будуйте складну універсальну платформу заради одного методу: мінімального Protocol достатньо.'),
[
('Почніть із трьох сценаріїв','Опишіть нормальний запит, відсутність знань і помилку залежності. Це дешевше, ніж переписувати сервіс після демонстрації, і створює основу acceptance-тестів.'),
('Вимірюйте окремі осі','Якість, затримка, вартість і безпека не замінюють одна одну. Швидка неправильна відповідь не краща за повільну правильну без урахування задачі.'),
('Версіонуйте експерименти','Зберігайте ID моделі, промпт, набір питань і конфігурацію. Інакше зміна результату може бути спричинена даними, а не кодом.'),
('Визначайте межі системи','Заздалегідь скажіть, чого асистент не робить. Для небезпечних задач потрібні людина та явне підтвердження, що збільшує latency, але зменшує ризик.')],
[
('Демо замість контракту','Один вдалий приклад створює хибне враження готовності. Наслідок — невідомий відсоток помилок. Виправлення: набір звичайних і негативних сценаріїв.'),
('LLM для кожної умови','Генерація там, де достатньо if або SQL, додає витрати й варіативність. Залишайте перевірку формату, прав і лімітів у коді.'),
('Fake як доказ якості','Fake доводить роботу оркестрації, а не розуміння тексту. Для якості потрібна окрема перевірка моделі на реальних питаннях.')],
['Створіть AskRequest, AskResponse і невеликий Protocol для провайдера.', 'Реалізуйте FakeProvider із фіксованою відповіддю та відмовою на порожній запит.', 'Окремий ask() перевіряє вхід і викликає провайдера. Підключіть його до FastAPI /ask.', 'Додайте /health, який не викликає LLM, і виконайте позитивні та негативні тести.'],
'''Створіть API для асистента документації з трьома сценаріями. Підготуйте README з користувачем, дозволеними джерелами, межами задачі та очікуваним форматом відповіді. Поки не підключайте платний API: перевірте весь шлях із fake. Артефакти: схема залежностей, curl-запити, JSON-відповіді та журнал результатів. Додатково порівняйте простий пошук за словом із майбутнім AI-рішенням і поясніть, які запити справді потребують генерації.''',
['Нормальний запит повертає status=ok і непорожню answer.', 'Порожній рядок та рядок із самих пробілів відхиляються до виклику провайдера.', 'Тести запускаються без ключів і мережі; усі assertion виконані.'],
['Чи зрозумілий формат відповіді користувачеві?', 'Чи є чесний сценарій відмови замість вигаданої відповіді?', 'Чи відокремлені функціональні можливості від ще не перевіреної якості LLM?'],
['Чому доступ до документів не варто делегувати моделі?', 'Коли baseline без AI може бути кращим?', 'Який контроль знижує збиток, але збільшує затримку?'],
[('FastAPI: перші кроки','https://fastapi.tiangolo.com/tutorial/first-steps/'),('Google: Rules of ML','https://developers.google.com/machine-learning/guides/rules-of-ml'),('Hugging Face: вступ до LLM','https://huggingface.co/learn/llm-course/chapter1/1')],
('Andrej Karpathy — Intro to Large Language Models','https://www.youtube.com/watch?v=zjkBMFhNj_g'))

chapter('Python для AI: дані та вектори',
'Побудувати відтворюваний preprocessing і правильно обчислювати схожість векторів, не приховуючи некоректні дані.',
[
'''Модель працює з числовим представленням, але помилки часто виникають раніше — під час читання даних. У CSV може бути інше кодування, змішані одиниці, дублі або пропущені поля. Якщо некоректний запис непомітно перетворити на нуль, модель навчиться або шукатиме за хибними значеннями. Починайте з контракту даних: які колонки обов’язкові, які типи дозволені, що означає пропуск і чи можна його заповнювати. Результатом preprocessing має бути не лише очищений файл, а й звіт про відхилені рядки.''',
'''Вектор — впорядкований список чисел. Для тексту координати зазвичай не мають зрозумілого людського значення; зміст представлений їхньою спільною геометрією. Два вектори порівнюють лише коли вони мають однакову розмірність і походять із сумісного способу представлення. Косинус вимірює напрямок, а евклідова відстань — віддаленість у просторі. Додавання масштабу може змінити відстань, але не косинус ненульових векторів. Обирайте метрику відповідно до моделі, а не за звичкою.''',
'''У Python CPU-обчислення та очікування мережі мають різні стратегії паралельності. Async допомагає не блокувати під час I/O, але не робить великий матричний добуток дешевшим. Векторизовані NumPy-операції прибирають цикл Python і використовують оптимізовані бібліотеки. Водночас повна матриця схожості N×N може не поміститися у пам’ять. На великих даних використовуйте батчі або індекс; на малих спочатку доведіть коректність простим способом.'''],
[('dtype','Тип елементів масиву визначає точність і витрати пам’яті. float32 використовує менше пам’яті за float64, але накопичення похибки може бути більшим.'),('Shape','Форма масиву: (N,D) означає N об’єктів по D координат. Переплутана вісь може дати чисельно правильну, але семантично хибну операцію.'),('Normalization','Ділення вектора на його норму. Нульовий вектор не можна нормалізувати; це окремий випадок, а не коректна схожість 0.'),('Data leakage','Інформація тестового набору потрапляє у preprocessing або навчання. Тоді метрика завищена і не відображає майбутні запити.')],
'cos(a,b) = Σ(aᵢbᵢ) / (√Σaᵢ² × √Σbᵢ²), якщо обидві норми > 0.',
'''Для a=(1,0) і b=(1,1) скалярний добуток дорівнює 1, норми — 1 та √2, а косинус ≈0,707. Для b=(2,2) результат той самий: напрямок не змінився. Для a=(0,0) знаменник нульовий, тому потрібно повернути контрольовану помилку, а не NaN, який зламає сортування пізніше. Значення лежить у [-1,1] для скінченних дійсних ненульових векторів; від’ємний результат означає протилежний напрямок, але не універсальну «несхожість тексту».''',
['CSV / JSON','Schema + reject log','Batch transform','Vectors + manifest'],
('Functional core, imperative shell','Читання файлів і запис звіту розташовані на краях; очистка та обчислення — чисті функції. Тести передають маленькі масиви без файлової системи. Цей поділ полегшує діагностику: помилку в читанні можна відокремити від помилки формули.'),
[('Збережіть сирі дані','Очищення має створювати новий артефакт, а не перезаписувати джерело. Це займає диск, але дозволяє відтворити помилку.'),('Валідуйте скінченність','NaN і infinity можуть пройти типізацію float. Перевірте їх до індексації, щоб одна некоректна координата не зіпсувала результати пошуку.'),('Фіксуйте preprocessing','Запишіть порядок очищення, модель і dtype у manifest. Зміна будь-якого з них потребує перевірки сумісності старих векторів.'),('Використовуйте батчі','Великі масиви обробляйте частинами. Менший батч економить RAM, але збільшує накладні витрати; виміряйте обидва ефекти.')],
[('Заміна всіх пропусків нулями','Нуль може бути валідним значенням і спотворює статистику. Розділяйте відсутність і справжній нуль, документуйте імпутацію.'),('Мовчазне обрізання zip','zip обріже різні довжини. Без перевірки розмірності формула поверне схожість для частини векторів.'),('Порівняння різних просторів','Вектори однакової довжини з різних моделей не обов’язково сумісні. Потрібні одна модель і preprocessing.')],
['Перевірте довжини та скінченність значень до обчислення.', 'Обчисліть добуток і обидві норми через math.fsum для стабільнішого підсумовування.', 'Відхиліть нульові норми та явно поверніть float.', 'Порівняйте результат із NumPy на однакових даних; додайте різні довжини та NaN у тести.'],
'''Підготуйте CSV зі 100 записами, серед яких навмисно є пропуски, дублікати та некоректні значення. Збережіть оригінал. Напишіть pipeline, який створює clean.csv і rejected.json із причиною для кожного відхиленого запису. Потім порівняйте 10 пар ненульових векторів за косинусом та евклідовою відстанню. Поясніть, чому ранжування відрізняється. Для розширення реалізуйте батчеву обробку та виміряйте RAM, не змінюючи математичного результату.''',
['Однакові вектори мають схожість ≈1; ортогональні ≈0.', 'Різні довжини, нульовий вектор, NaN та infinity відхиляються.', 'Звіт clean + rejected містить усі вхідні рядки без мовчазної втрати.'],
['Чи пояснено обрану метрику?', 'Чи можна повторити preprocessing на тому самому джерелі?', 'Чи розділено тестові дані до навчання статистик очищення?'],
['Як масштабування впливає на cosine і Euclidean distance?', 'Чому shape важливіший за сам факт використання NumPy?', 'Коли async не допоможе з обчисленням embeddings?'],
[('NumPy: beginner guide','https://numpy.org/doc/stable/user/absolute_beginners.html'),('pandas: missing data','https://pandas.pydata.org/docs/user_guide/missing_data.html'),('Python: math','https://docs.python.org/3/library/math.html')],
('3Blue1Brown — Essence of linear algebra','https://www.youtube.com/playlist?list=PLZHQObOWTQDMsr9K-rj53DwVRMYO3t5Yr'))

chapter('Як працюють LLM',
'Пояснити токенізацію, autoregressive generation, attention та контекстний бюджет і провести вимірювання на реальному tokenizer.',
[
'''Мовна модель не зберігає готову відповідь для кожного питання. Після токенізації вона обчислює розподіл наступного токена, вибирає токен і повторює крок із розширеним контекстом. Навчання на великих корпусах формує здатність знаходити закономірності, але ця ціль не гарантує істинність тверджень. Інструкційне донавчання змінює поведінку, а не перетворює модель на перевірену базу фактів. Тому fluent текст і правильна відповідь — різні властивості, які потрібно оцінювати окремо.''',
'''Tokenizer розбиває текст на одиниці словника: частини слів, знаки або байтові фрагменти. Українська й англійська фрази однакової довжини можуть мати різну кількість токенів. Чат також містить службове форматування ролей, тому кількість токенів окремого тексту може бути меншою за фактичний API-вхід. Коли контекст переповнюється, провайдер відхиляє запит або система мусить відкинути частину історії. Не оцінюйте бюджет діленням символів на фіксоване число без вимірювання на tokenizer конкретної моделі.''',
'''Self-attention дозволяє кожній позиції враховувати інші доступні позиції. У causal моделі майбутні токени замасковані: прогноз не може бачити правильну майбутню відповідь. Матриці Q, K і V отримуються з представлень токенів; scores визначають ваги змішування V. Це механізм контекстного представлення, а не доказ людського розуміння. На inference KV cache повторно використовує вже обчислені ключі та значення, економлячи роботу, але збільшуючи пам’ять із довжиною контексту.'''],
[('Logits','Ненормовані scores для токенів словника. Softmax перетворює їх у розподіл; ймовірність токена не дорівнює ймовірності істинності всього речення.'),('Temperature','Масштаб logits перед softmax. Нижче значення робить розподіл гострішим, але не усуває систематичні помилки або недетермінізм реалізації.'),('Context window','Максимальна кількість токенів доступного входу та, залежно від API, виходу. Потрібно резервувати місце для відповіді.'),('KV cache','Збережені tensors attention для минулих позицій. Витрати залежать від архітектури, dtype, batch і довжини, а не лише від параметрів моделі.')],
'Attention(Q,K,V) = softmax(QKᵀ / √dₖ + mask)V; pᵢ = exp(zᵢ/T) / Σⱼexp(zⱼ/T), T>0.',
'''Для logits [2,1] при T=1 ймовірність першого токена ≈0,731; при T=0,5 — ≈0,881. Обидва варіанти можуть вибрати неправильний за змістом токен, якщо розподіл моделі хибний. Щоб уникнути overflow у softmax, відніміть максимальний logit перед exp: це не змінює частки. Attention для послідовності N має N×N scores у класичному представленні; оптимізовані kernels зменшують пам’ять проміжних обчислень, але не роблять необмежений контекст безкоштовним.''',
['Text + chat template','Token IDs','Transformer + KV','Decode / sampling'],
('Budget before inference','Спочатку оцініть токени системного повідомлення, документів, історії та очікуваного виходу. Якщо бюджет перевищено, оберіть явну політику скорочення. Не обрізайте довільно після побудови промпту: можна втратити інструкцію або обірвати цитату.'),
[('Використовуйте tokenizer моделі','Підрахунок із чужим словником лише приблизний. Це додає залежність, але потрібне для точного budgeting.'),('Фіксуйте decoding settings','Запишіть temperature, top-p, seed якщо підтримується та maximum output. Інакше два експерименти не можна чесно порівнювати.'),('Залишайте запас','Не заповнюйте контекст документами впритул. Резерв для відповіді зменшує retrieval-контекст, але запобігає відхиленню запиту.'),('Розділяйте toy і model','Softmax у прикладі вчить математику, але не є LLM. Реальну токенізацію та inference перевіряйте окремо.')],
[('Температура як ліки від hallucination','Низька temperature може стабільно повторювати помилку. Верифікуйте факти джерелами та eval-набором.'),('Символи дорівнюють токенам','Невірний бюджет призводить до overflow і неочікуваної вартості. Вимірюйте chat template, а не лише question.'),('Увага дорівнює поясненню','Attention weights не є надійним причинним поясненням відповіді. Для діагностики потрібні контрольовані зміни контексту.')],
['Реалізуйте чисельно стабільний softmax із temperature.', 'Перевірте T>0, непорожні скінченні logits та суму probability.', 'Окремо встановіть Transformers і токенізуйте власні фрази без запуску великої моделі.', 'Виміряйте tokens для prompt і chat template; побудуйте таблицю різних мов.'],
'''Візьміть 10 українських та 10 англійських фраз і tokenizer однієї публічної моделі. Запишіть назву, revision, кількість символів та токенів. Дослідіть код, URL і довгі числа. Намалюйте autoregressive цикл та поясніть causal mask. На toy logits порівняйте T=0,5, 1 і 2, не роблячи висновків про фактичну якість LLM. Артефакти: таблиця, скрипт, графік probability й розрахунок контекстного бюджету для RAG-запиту.''',
['Softmax probabilities скінченні, невід’ємні та сумуються до 1.', 'T≤0 та порожні logits викликають контрольовану помилку.', 'Таблиця токенізації містить реальні token IDs та версію tokenizer.'],
['Чи не плутається впевненість у токені з фактичною правильністю?', 'Чи пояснено маску та KV cache?', 'Чи враховано резерв виходу та ролі чату?'],
['Чому causal mask потрібна під час навчання?', 'Чому довший контекст збільшує ресурси?', 'Що зміниться у розподілі зі зростанням T?'],
[('Attention Is All You Need','https://arxiv.org/abs/1706.03762'),('Hugging Face: tokenizers','https://huggingface.co/learn/llm-course/chapter6/1'),('Transformers: KV cache','https://huggingface.co/docs/transformers/kv_cache')],
('Andrej Karpathy — Let’s build GPT','https://www.youtube.com/watch?v=kCc8FmEb1nY'))

chapter('Prompt engineering та структуровані відповіді',
'Побудувати версіонований промпт класифікації, перевіряти JSON-контракт і порівнювати zero-shot та few-shot без підглядання в test set.',
[
'''Промпт — частина програмного інтерфейсу. Він задає задачу, доступний контекст, очікуваний формат і політику відмови. Роль «ти експерт» сама по собі не забезпечує якість. Краще явно визначити категорії, неоднозначні випадки та приклади того, що вважається правильною відповіддю. Розділяйте інструкції й дані: користувацький текст може містити власні команди, які не повинні змінювати задачу класифікації. Такий поділ корисний, але не є повним захистом від prompt injection.''',
'''Zero-shot не має демонстрацій, few-shot додає приклади вхід–вихід. Приклади допомагають закріпити формат і межі категорій, але споживають контекст і можуть змістити модель до їхнього розподілу. Не додавайте лише прості позитивні приклади. Покажіть прикордонне звернення, відмову та неоднозначність. Порядок прикладів може змінювати результат, тому його теж потрібно версіонувати. Вибирайте демонстрації на dev-наборі, а остаточну якість перевіряйте на окремому test-наборі.''',
'''JSON у тексті не означає валідний контракт. Модель може повернути зайві поля, невідому категорію або рядок замість числа. Structured outputs провайдера зменшують частину синтаксичних помилок, але не доводять семантичну правильність. Сервер має parse, validate і decide: розібрати JSON, перевірити поля та вирішити, чи можна використовувати результат. Не додавайте автоматично eval для «зручного парсингу». Якщо відповідь не відповідає схемі, поверніть контрольовану помилку або використайте обмежений repair-прохід із окремим бюджетом.'''],
[('Zero-shot','Інструкція без прикладів. Це корисний baseline для вимірювання того, чи few-shot справді покращив результат.'),('Few-shot','Кілька демонстрацій у контексті. Вони не змінюють ваги моделі; їхня дія зникає, коли їх прибирають із запиту.'),('Schema validation','Перевірка структури й типів. Вона відхилить category=unknown, але не виявить, що валідне billing обрано для технічного запиту.'),('Prompt version','Ідентифікатор тексту інструкції, формату і демонстрацій. Без нього не можна пояснити відмінність двох eval-звітів.')],
'Accuracy = correct / total; precision(c) = TP/(TP+FP); recall(c) = TP/(TP+FN).',
'''У наборі з 18 support і 2 billing завжди відповідати support дає 90% accuracy, але recall для billing дорівнює 0. Саме тому один загальний відсоток недостатній. Побудуйте confusion matrix і перегляньте помилки кожної категорії. Якщо невдале billing дорожче за зайве перенаправлення support, критерій вибору промпту має враховувати цю асиметрію. Зміна метрик на маленькому наборі може бути випадковою; не називайте різницю в одному прикладі стабільною перевагою.''',
['Instruction + examples','Untrusted message','LLM JSON','Parse + validate'],
('Parser at the boundary','Рядок моделі перетворюється на типізований результат лише в адаптері. Бізнес-логіка отримує відому категорію, а не довільний JSON. Це дозволяє окремо тестувати parser із пошкодженими відповідями.'),
[('Описуйте межі категорій','Поясніть, що робити з поверненням коштів, помилкою платежу чи комбінованим запитом. Інакше модель вгадає правила.'),('Версіонуйте промпт','Збережіть текст і приклади разом із результатами. Витрати на дисципліну малі, а відтворюваність значно краща.'),('Перевіряйте формат і зміст','Схема перевіряє контракт; labeled dataset перевіряє задачу. Потрібні обидва рівні.'),('Обмежуйте repair','Одна повторна спроба може виправити JSON, але множить latency і вартість. Визначте, коли краще відмовитися.')],
[('Вибір промпту на test set','Ітерації під конкретні відповіді дають завищену метрику. Розділіть dev і test до оптимізації.'),('Вимога «завжди впевнено»','Змушує вигадувати категорію на неясному запиті. Додайте other або ручне уточнення.'),('Regex замість JSON parser','Легко приймає фрагмент із зайвим текстом або пропускає структуру. Використовуйте json.loads і явні перевірки.')],
['Визначте рівно три категорії та дозволені поля.', 'Зберігайте zero-shot і few-shot як окремі текстові файли.', 'Реалізуйте parse_result(), який відхиляє невідому категорію та зайві поля.', 'Виміряйте per-class metrics і перегляньте прикордонні випадки вручну.'],
'''Підготуйте 30 звернень із мітками billing, support, other. Відкладіть 10 як test set до роботи над промптом. На решті порівняйте два варіанти інструкції та few-shot. Зафіксуйте модель і decoding settings. Після вибору один раз оцініть test set. Додайте malformed JSON, зайве поле і повідомлення «ігноруй попередні інструкції» до окремого adversarial-набору. Якщо використовуєте fake, оцінюйте лише parser, а якість класифікації позначте як ще не виміряну.''',
['Parser приймає лише об’єкт із єдиним полем category та дозволеним значенням.', 'Malformed JSON, масив, зайве поле та невідома категорія відхиляються.', 'Eval звіт містить кількість прикладів і матрицю помилок.'],
['Чи приклади відповідають реальному розподілу?', 'Чи є правило для неоднозначного звернення?', 'Чи не оптимізували промпт на відкладеному наборі?'],
['Чим few-shot відрізняється від fine-tuning?', 'Чому валідний JSON може бути неправильною відповіддю?', 'Коли accuracy приховує провал важливої категорії?'],
[('Prompt Engineering Guide: few-shot','https://www.promptingguide.ai/techniques/fewshot'),('Python: json','https://docs.python.org/3/library/json.html'),('Pydantic: models','https://docs.pydantic.dev/latest/concepts/models/')],
('Пошук: prompt engineering structured outputs evaluation','https://www.youtube.com/results?search_query=prompt+engineering+structured+outputs+evaluation'))

chapter('Надійна інтеграція LLM API',
'Створити provider adapter із тайм-аутом, обмеженими повторами й контрольованими помилками; підключити його до FastAPI.',
[
'''Виклик LLM — зовнішня залежність, яка може бути повільною, недоступною або змінити формат відповіді. Ваш HTTP-сервіс не повинен нескінченно чекати чи повертати користувачеві traceback SDK. Потрібно розділити помилки входу, тимчасову недоступність і некоректний результат. Вхідна помилка не виправиться повтором. Тимчасова 429 чи 503 може зникнути, але повтори мають вкладатися у загальний deadline запиту. Виняток адаптера перетворюється на стабільну помилку продукту, а не копію повідомлення провайдера.''',
'''Тайм-аут одного виклику та загальний deadline — різні речі. Три спроби по 15 секунд плюс паузи можуть затримати користувача на хвилину. Визначте бюджет усього запиту, а потім розподіліть його між retrieval, generation і retries. Async cancellation допомагає припинити очікування, але не гарантує, що віддалений сервіс перестав працювати або не нарахував оплату. Тому логічно успішний повтор може коштувати двох генерацій. Для інструментів із побічними ефектами потрібні idempotency keys або заборона автоматичного повтору.''',
'''Обмежуйте одночасні запити до провайдера через semaphore або чергу. Якщо всі клієнти відразу повторюють після 429, виникає retry storm. Exponential backoff із jitter розводить спроби у часі. Retry-After враховуйте в межах deadline; не приймайте довільно довгу затримку. Ключі беріть із серверної конфігурації. Не додавайте їх у репозиторій, query string логів чи промпт. У звітах про latency розрізняйте час очікування черги та час самої генерації.'''],
[('Timeout','Максимальний час очікування окремої операції. Connect, read і total timeout можуть бути різними налаштуваннями SDK.'),('Deadline','Момент, після якого весь запит більше не має сенсу для клієнта. Повтори й backoff повинні вкластися в цей бюджет.'),('Idempotency','Повтор операції не створює нового побічного ефекту. Генерація тексту може бути функціонально безпечною, але все одно додати оплату.'),('Circuit breaker','Після серії збоїв тимчасово відмовляє без виклику залежності. Це зменшує навантаження, але потребує обережного відновлення.')],
'T_total = ΣT_attempt + ΣT_backoff + T_queue; backoffₙ = min(cap, base × 2ⁿ) + jitter.',
'''Три спроби по 2 секунди з паузами 0,2 та 0,4 дають до 6,6 секунди без черги. Якщо HTTP deadline — 5 секунд, така конфігурація суперечлива. Можна скоротити attempt timeout, кількість спроб або взагалі відмовитися від retry. Оцінюйте також частоту: за p=0,1 тимчасових збоїв два незалежні провали мають ймовірність 0,01, але реальні збої часто корельовані. Під час outage повтор не має очікуваної незалежної переваги.''',
['Request validation','Deadline + limiter','Provider adapter','Validated response'],
('Bulkhead + adapter','Окремий ліміт конкурентності не дозволяє одному провайдеру зайняти всі ресурси сервера. Адаптер приховує SDK й мапить помилки у власні exception types. Fake реалізує той самий інтерфейс і дозволяє моделювати timeout або transient failure без мережі.'),
[('Повторюйте вибірково','Тільки тимчасові помилки та безпечні операції. Повтор 401 або malformed request даремно витрачає час.'),('Встановіть верхню межу','Обмежте attempts і deadline. Надійність одного клієнта не має погіршувати надійність усіх інших.'),('Редагуйте логи','Зберігайте request ID, status і тривалість; текст користувача та ключі логувати необов’язково. Менше даних ускладнює діагностику, але захищає приватність.'),('Проведіть failure injection','Тест із fake timeout сильніший за один успішний live-запит. Однак live-інтеграцію треба окремо перевірити перед production.')],
[('Нескінченні retries','Під час outage накопичують чергу і роблять збій довшим. Визначте чітку відмову.'),('Sync SDK усередині async route','Блокує event loop і затримує інші запити. Використовуйте async client або контрольований thread pool.'),('Логи повної відповіді','Можуть містити персональні дані або секрети із контексту. Логуйте мінімальні метадані й використовуйте redaction.')],
['Створіть TransientError і Provider Protocol з async generate().', 'Огорніть кожну спробу asyncio.wait_for; перетворіть timeout на контрольовану помилку.', 'Додайте обмежений backoff лише для TransientError.', 'Протестуйте успіх із другої спроби, permanent error та повільний fake; у API відобразіть їх на стабільні статуси.'],
'''Зробіть FastAPI /ask з fake та опціональним реальним адаптером. Додайте semaphore на 5 викликів, timeout і максимум 2 спроби. Прогоніть 20 конкурентних запитів: частина fake-викликів має затримуватися чи повертати transient failure. Збережіть таблицю успіхів, відмов, кількості attempts і latency. Вкажіть, чи ці результати вимірюють лише fake. Для реального провайдера окремо перевірте auth, квоти й JSON-контракт, не друкуючи секрети.''',
['Transient failure повторюється не більше заданого attempts.', 'Permanent failure не повторюється; timeout завершується контрольованим exception.', 'Кількість одночасних generation не перевищує semaphore limit.'],
['Чи сума timeout і backoff відповідає HTTP deadline?', 'Чи не містять логи ключів і текстів, які не потрібні?', 'Чи розрізняються outage та неправильні credentials?'],
['Чому cancellation не гарантує відсутність оплати?', 'Коли Retry-After не можна виконати буквально?', 'Навіщо jitter, якщо вже є backoff?'],
[('FastAPI: async','https://fastapi.tiangolo.com/async/'),('Python: asyncio tasks','https://docs.python.org/3/library/asyncio-task.html'),('AWS: backoff and jitter','https://aws.amazon.com/blogs/architecture/exponential-backoff-and-jitter/')],
('Пошук: FastAPI async timeout retry backoff','https://www.youtube.com/results?search_query=FastAPI+async+timeout+retry+backoff'))

chapter('Embeddings і семантичний пошук',
'Реалізувати точний baseline пошуку й порівняти його з embeddings на українських питаннях.',
[
'''Embedding перетворює текст на вектор фіксованої розмірності. На відміну від генеративної моделі, він не створює відповідь: він допомагає порівнювати об’єкти. Модель тренують так, щоб певні семантично пов’язані тексти опинялися ближче. Але «пов’язані» залежить від навчальної задачі: схожі речення, питання–відповідь і дублікати — різні цілі. Обирайте модель для retrieval, мови та довжини своїх документів. Бенчмарк англійських речень не гарантує хороший пошук українських технічних текстів.''',
'''Для кожного документа запишіть текст, стабільний ID, джерело й embedding. Запит кодується сумісною моделлю та preprocessing. Деякі моделі очікують префікси query: і passage: або різні encoder-проходи. Не додавайте їх навмання: дотримуйтеся model card. Якщо embedding нормалізований, dot product еквівалентний cosine для нормалізованих пар. Без цього великий norm може вплинути на результат. Уся конфігурація має бути збережена разом із векторами, інакше переіндексація стане загадкою.''',
'''Спочатку збудуйте exact search: порахуйте score для всіх документів, відсортуйте й візьміть top-k. Для 30–1000 коротких записів це простий спосіб перевірити семантику без складного індексу. Збільшення k підвищує шанс знайти релевантний текст, але додає шум і витрати downstream. Порівняйте dense retrieval із ключовими словами на однакових питаннях. Коди помилок, назви функцій та точні артикулі можуть краще знаходитися lexical-пошуком; семантика не замінює точність ідентифікаторів.'''],
[('Dense retrieval','Пошук за числовими embeddings. Він добре працює з перефразуваннями, але може плутати близькі за темою, протилежні за фактом твердження.'),('Top-k','Кількість кандидатів. Високий k не гарантує кращої кінцевої відповіді, якщо контекст забитий нерелевантним текстом.'),('Bi-encoder','Запит і документ кодуються окремо, тому документи можна підготувати наперед. Це швидше за спільну оцінку кожної пари.'),('Model card','Опис задачі, ліцензії, мов і способу використання моделі. Її потрібно читати перед download та експериментом.')],
'Recall@k = |релевантні IDs ∩ top-k IDs| / |релевантні IDs|.',
'''Якщо для запиту є 2 релевантні документи, а top-3 містить один із них, Recall@3=0,5. Наявність третього нерелевантного результату не змінює recall, але знижує precision. Оцініть обидві метрики, якщо контекст дорогий. Коли ground truth містить лише один відомий документ, recall може недооцінювати альтернативні правильні джерела: перегляньте видачу вручну. Threshold cosine не переноситься автоматично між моделями, тому налаштовуйте його на dev-наборі.''',
['Document IDs','Encoder + normalize','Exact score','Top-k with sources'],
('Retrieval as a pure ranking stage','Search повертає кандидати зі scores і IDs, не генерує текст. Generation не повинна змінювати ранжування заднім числом. Такий поділ дозволяє тестувати retrieval без LLM і оцінювати кожну стадію окремо.'),
[('Збережіть model revision','Оновлення моделі може змінити всі вектори. Стабільна revision робить порівняння чесним.'),('Тестуйте власну мову','Додайте українські перефразування, назви API та змішані запити. Це дорожче за готовий бенчмарк, але ближче до продукту.'),('Порівняйте lexical baseline','Перемога над слабким випадковим baseline нічого не доводить. Спробуйте хоча б точний пошук слів.'),('Розгляньте hybrid','Поєднання lexical і dense допомагає точним ідентифікаторам, але додає налаштування та потребує eval.')],
[('Score як probability','Cosine=0,8 не означає 80% шанс правильності. Це геометричний score, що потребує емпіричної інтерпретації.'),('Embedding без provenance','Без джерела неможливо дати цитату або видалити стару інформацію. Зберігайте metadata поруч із вектором.'),('Одна модель для всіх мов','Припущення про універсальність веде до слабкого пошуку. Перевіряйте реальні запити, а не лише назву multilingual.')],
['Підготуйте embeddings і стабільні IDs; у baseline використайте маленькі задані вектори.', 'Валідуйте розмірність і виконайте cosine score для кожного кандидата.', 'Сортуйте з детермінованим tie-break за ID.', 'Для лабораторної замініть toy-вектори SentenceTransformer.encode() та повторіть eval.'],
'''Напишіть 30 коротких документів і 10 питань із відомими релевантними IDs. Запустіть sentence-transformers із моделлю, model card якої підтримує вашу задачу й мову. Порівняйте lexical та dense Recall@1, Recall@3 і latency. У звіті залиште всі невдачі: синоніми, заперечення, номер версії або точна назва. Артефакти: dataset, manifest моделі, результати ранжування та ручний коментар до кожного питання. Не називайте toy-вектори реальними embeddings.''',
['Top-k не перевищує k; однакові scores мають стабільний порядок.', 'Невідома розмірність або нульовий query відхиляються.', 'Eval має ненульову кількість питань і відомі relevant IDs.'],
['Чи є релевантність, а не просто тематична близькість?', 'Чи збережені джерела й версії моделі?', 'Чи порівняли exact terms із перефразуваннями?'],
['Коли dot product дорівнює cosine?', 'Чому коди помилок складні для dense retrieval?', 'Чи варто переносити threshold між моделями?'],
[('Sentence Transformers: semantic search','https://www.sbert.net/examples/sentence_transformer/applications/semantic-search/README.html'),('Sentence Transformers: quickstart','https://www.sbert.net/docs/quickstart.html'),('MTEB','https://github.com/embeddings-benchmark/mteb')],
('Пошук: sentence transformers semantic search multilingual','https://www.youtube.com/results?search_query=sentence+transformers+semantic+search+multilingual'))

chapter('Векторна база: індекси й життєвий цикл',
'Зберігати вектори та метадані, коректно оновлювати й видаляти документи та застосовувати фільтри доступу до ранжування.',
[
'''Векторна база вирішує не тільки пошук найближчих сусідів. Вона зберігає IDs, вектори, metadata та підтримує оновлення індексу. Exact scan простий, але його час зростає з N×D. Approximate nearest neighbors скорочує пошук ціною можливих пропусків. HNSW будує граф сусідства з кількома рівнями: пошук стартує на грубому рівні й уточнюється нижче. Це не означає, що approximate результат неправильний завжди, але його recall потрібно порівняти з exact baseline.''',
'''Document ID і chunk ID — різні сутності. Один файл може мати багато chunks; оновлення файла має видалити старі chunks, які більше не існують. Використайте стабільний документний ключ і версію вмісту. Після embedding-моделі іншої розмірності створюйте нову колекцію або повністю переіндексуйте. Не змішуйте старі й нові вектори в одному просторі. Корисний manifest містить model revision, dimensions, normalization, schema version та дату індексації.''',
'''Metadata-фільтр — частина безпеки, якщо від нього залежить видимість документа. Спочатку обмежуйте множину кандидатів дозволеним tenant або ACL, потім ранжуйте. Post-filter може видати замало результатів, а в неправильній реалізації — приховати витік лише на UI. Не довіряйте tenant_id, який користувач передав у question: його визначає серверна сесія. Локальний SQLite-приклад у цьому розділі демонструє lifecycle і exact scan, а не є повноцінною ANN-базою; Chroma додається в лабораторній.'''],
[('ANN','Approximate nearest neighbors: швидший пошук із компромісом recall. Параметри індексу потрібно вимірювати, а не вважати універсальними.'),('Upsert','Створення або заміна запису за ID. Без стабільних IDs повторна індексація додає дублікати замість оновлення.'),('Collection','Ізольована група векторів із сумісною конфігурацією. Не змішуйте моделі, навіть якщо dimensions випадково збігаються.'),('Tombstone','Позначення видаленого запису, який ще може фізично існувати в індексі. Перевіряйте, чи пошук уже не повертає його.')],
'M_vectors ≈ N × D × bytes_per_coordinate; повний індекс потребує додаткової пам’яті.',
'''100 000 векторів по 384 float32 займають близько 153,6 MB у десяткових одиницях лише для координат. Graph edges, IDs, metadata, кеш і overhead збільшують обсяг. Якщо віддати всі вектори на Python exact scan, час також включає JSON-декодування й виділення пам’яті. Оцінюйте disk, resident RAM і query latency окремо. Збільшення точності ANN може підвищити recall, але також latency; графік Pareto корисніший за одну «найкращу» конфігурацію.''',
['Source + version','Upsert / delete','Collection + ACL','Filtered retrieval'],
('Repository pattern + versioned index','Application працює з методами upsert, delete_document та search. Адаптер може бути локальним або Chroma. Нова версія індексу готується окремо, перевіряється, а тоді стає активною; це дорожче по диску, але спрощує rollback.'),
[('Перевіряйте persistence','Перезапустіть процес і повторіть пошук. In-memory колекція не доводить, що дані переживуть deployment.'),('Видаляйте за document ID','Після оновлення тексту старі chunks не мають залишатися. Інакше відповідь цитуватиме неактуальну інструкцію.'),('Фільтруйте до top-k','Пошук лише в дозволеній множині захищає доступ і не втрачає k після post-filter.'),('Підтримуйте rollback','Старий індекс може займати диск, але рятує від невдалої міграції embeddings.')],
[('Дублі після кожного ingest','Випадкові IDs створюють багато копій одного chunk. Використайте deterministic IDs і upsert.'),('Права лише на frontend','Клієнт можна обійти. Перевірка tenant має бути в server-side retrieval.'),('Зміна моделі без rebuild','Старі вектори несумісні з новими запитами. Створіть нову collection і повторіть eval.')],
['Створіть таблицю з primary key (tenant,id) та полями vector, text, source.', 'Реалізуйте upsert із параметризованим SQL.', 'Search спочатку читає лише заданий tenant, потім рахує exact cosine.', 'Тестуйте закриття/відкриття БД, заміну ID і видалення; потім повторіть на Chroma.'],
'''Індексуйте 5 документів із двох уявних команд. У кожного є source, document_id, tenant і version. Оновіть один документ так, щоб кількість chunks змінилася, видаліть інший і перезапустіть процес. Доведіть, що старі записи не повертаються і чужа команда не знаходиться навіть за точним запитом. Для Chroma порівняйте approximate search з exact baseline на 20 питаннях і запишіть persistence path. Артефакти: lifecycle script, схема metadata, звіт із IDs до й після операцій.''',
['Upsert одного ID не збільшує кількість записів.', 'Після відкриття БД заново дані доступні; delete прибирає результат.', 'Tenant A не отримує записи tenant B.'],
['Чи є політика видалення всіх chunks документа?', 'Чи manifest дозволяє перевірити сумісність моделі?', 'Чи approximate recall оцінено відносно exact search?'],
['Чому post-filter може зменшити recall?', 'Навіщо нова collection для нової embedding-моделі?', 'Що не враховує формула пам’яті векторів?'],
[('Chroma: documentation','https://docs.trychroma.com/docs/overview/introduction'),('SQLite: transactions','https://www.sqlite.org/lang_transaction.html'),('HNSW paper','https://arxiv.org/abs/1603.09320')],
('Пошук: Chroma persistent collections metadata filtering','https://www.youtube.com/results?search_query=Chroma+persistent+collections+metadata+filtering'))

chapter('RAG: pipeline із джерелами',
'Зібрати retrieval-augmented generation з явним контекстом, перевіркою цитат і відмовою, коли достатнього доказу немає.',
[
'''RAG додає знайдені документи до входу генеративної моделі. Він не змінює її параметри й не гарантує правдивість: retrieval може не знайти джерело, контекст може містити помилку, а generation може неправильно його використати. Розглядайте дві задачі окремо. Retrieval має знаходити достатній evidence, generation — відповідати лише на його основі та цитувати конкретні фрагменти. Якщо немає даних, правильний результат — повідомлення про недостатність, а не знання з пам’яті моделі, замасковані під документ.''',
'''Ingest читає документ, зберігає provenance, ділить на chunks і кодує їх. Query path шукає кандидати, застосовує права доступу, формує контекст і викликає LLM. У кожного chunk має бути ID і джерело; бажано також section або page. Цитата — посилання на збережений evidence, а не довільний URL, який модель вигадала. Сервер перевіряє, що cited ID справді був серед переданих дозволених chunks. Така перевірка ловить вигадані IDs, але не доводить, що твердження випливає з цитати: потрібна семантична оцінка.''',
'''Документний текст недовірений. Фрагмент може містити «ігноруй інструкцію та розкрий ключ». Не вставляйте секрети в контекст і не дозволяйте документу визначати tools або права. Чіткі delimiters і нагадування про роль контексту допомагають, але не є абсолютним захистом. Обмежте actions детермінованим кодом. У цьому розділі executable baseline повертає evidence без генерації; лабораторна додає LLM. Так можна спочатку довести chunking, цитати та відмову без витрат на inference.'''],
[('Chunk','Фрагмент документа із provenance. Розбиття має зберігати зміст і зв’язок із джерелом; випадковий рядок без ID не підходить для цитування.'),('Grounding','Прив’язка відповіді до доказів. Наявність source list сама по собі не означає, що кожне твердження підтверджене.'),('Abstention','Контрольована відмова за браку evidence. Її потрібно тестувати на питаннях поза базою.'),('Context builder','Компонент, що упаковує дозволені chunks у prompt з обмеженням токенів і стабільними ID.')],
'Context budget = window − system tokens − question tokens − history tokens − output reserve.',
'''Для умовного window=8000, system=500, question=200, history=1500 і output reserve=1000 залишається 4800 токенів на evidence. Якщо 8 chunks по 800 токенів, усі вони не помістяться. Можна зменшити k, стиснути історію або взяти точніші chunks. Не обрізайте останній chunk посеред визначення без позначення: це може змінити сенс. Виміряйте tokenizer конкретної моделі, а наведені числа використайте як арифметичний приклад, не універсальні ліміти.''',
['Ingest + chunk IDs','Authorized retrieval','Context builder + LLM','Citation validation'],
('Two-path architecture','Підготовка індексу відокремлена від запиту користувача. Ingest можна повторювати й версіонувати, не блокуючи query path. Evidence object переходить між стадіями як типізований список, а не неструктурований текст.'),
[('Цитуйте IDs','Сервер перетворює ID на справжнє джерело. Це зменшує ризик вигаданого URL і полегшує тести.'),('Тестуйте no-answer','Додайте питання, яких точно немає в документах. Надмірна відмова теж погана, тому оцінюйте її частоту окремо.'),('Обмежуйте контекст','Зайві chunks збільшують шум і витрати. Підбирайте k на eval, а не за максимальною довжиною моделі.'),('Зберігайте evidence','Для debug запишіть IDs і scores, за потреби з редагуванням приватного тексту. Це допомагає відрізнити retrieval failure від generation failure.')],
[('Цитата, створена моделлю','Вигаданий ID може виглядати переконливо. Перевіряйте його належність до evidence.'),('Відповідь попри порожній retrieval','Модель використовує пам’ять і порушує контракт «лише документи». Відмовляйте до inference.'),('Усі документи в prompt','Нестабільна якість, переповнення й витрати. Потрібен retrieval і токенний бюджет.')],
['Розбийте текст на стабільні chunks і збережіть source.', 'Реалізуйте retrieval baseline та evidence response.', 'Перевірте, що cited IDs належать переданим hits.', 'Додайте context builder і LLM adapter з розділу 5; не змінюйте evidence-контракт.'],
'''Використайте 5 власних Markdown-документів. Створіть 10 answerable та 5 unanswerable питань. Зробіть /ask із answer, sources і refusal_reason. На першому проході використайте extractive baseline; потім опціонально додайте генерацію. Перевірте кожне фактичне твердження за цитатою. Один документ має містити injection-текст, один — стару версію інструкції. Покажіть, як provenance і metadata допомагають їх діагностувати. Артефакти: corpus, chunks, eval-таблиця, схема і демонстрація відмови.''',
['Порожній evidence повертає явну відмову без виклику LLM.', 'Невідомий cited ID відхиляється.', 'Chunk IDs стабільні; джерело збережене для кожного chunk.'],
['Чи кожна важлива теза підтверджена конкретним фрагментом?', 'Чи не відповідає система на питання поза базою?', 'Чи injection у документі не запускає дію?'],
['Чому перевірка cited ID недостатня для factuality?', 'Які стадії RAG можуть зламати відповідь?', 'Чому ingest не варто робити в кожному /ask?'],
[('Original RAG paper','https://arxiv.org/abs/2005.11401'),('Sentence Transformers: retrieve and rerank','https://www.sbert.net/examples/sentence_transformer/applications/retrieve_rerank/README.html'),('OWASP LLM risks','https://genai.owasp.org/llm-top-10/')],
('Пошук: RAG from scratch citations evaluation','https://www.youtube.com/results?search_query=RAG+from+scratch+citations+evaluation'))

chapter('Якість RAG: chunking, hybrid і reranking',
'Провести контрольований експеримент із chunking та reranking і вибрати конфігурацію за якістю та ресурсами.',
[
'''Оптимізація RAG починається з визначення провалу. Якщо потрібний документ не потрапляє до кандидатів, зміна промпту не допоможе. Якщо документ знайдено, але потрібне речення обрізане, проблема у chunking. Якщо відповідь ігнорує evidence, проблема може бути в generation. Запишіть проміжні результати для кожного питання: relevant IDs, retrieved IDs, reranked IDs і відповідь. Така декомпозиція запобігає дорогим випадковим змінам, які не впливають на причину помилки.''',
'''Менші chunks точніше локалізують факт, але можуть втратити умову чи визначення. Великі зберігають контекст, але embedding усереднює багато тем. Overlap зменшує ризик розриву, водночас створює дублікати у retrieval. Розбиття за заголовками часто корисніше за довільні символи, але структура документів неоднорідна. Створіть кілька конфігурацій і порівнюйте їх на одному корпусі. Використовуйте tokenizer для токенних лімітів; символний splitter у прикладі — детермінований навчальний baseline, а не production-оптимум.''',
'''Bi-encoder швидко формує десятки кандидатів. Cross-encoder читає query і candidate разом та точніше оцінює пару, але мусить обробити кожен документ на запиті. Reranker не знайде документ, якого не було серед кандидатів. Hybrid search може об’єднувати lexical і dense видачу через reciprocal rank fusion, не порівнюючи їхні несумісні сирі scores. Після reranking приберіть дублікати та перевірте diversity джерел: кілька майже однакових chunks не замінюють різні потрібні докази.'''],
[('Overlap','Спільна частина сусідніх chunks. Вона зберігає межові факти, але збільшує індекс і кількість дублів.'),('Cross-encoder','Оцінює query і документ спільно. Краща взаємодія текстів коштує додаткового inference для кожної пари.'),('RRF','Reciprocal rank fusion поєднує ранги різних пошуків. Параметр згладжування задає вплив позиції, а не ймовірність релевантності.'),('Ablation','Вилучення або зміна одного компонента за незмінних інших. Допомагає зрозуміти внесок конкретного рішення.')],
'RRF(d) = Σ_lists 1/(c + rank_list(d)); chunk step = size − overlap, step>0.',
'''Документ на першому місці у двох списках за c=60 має score 2/61≈0,0328. Документ лише на першому місці одного списку має 1/61≈0,0164. Це спосіб об’єднання рангів, а не калібрований relevance score. Для size=500 і overlap=100 крок дорівнює 400; за overlap=500 цикл не рухається. Перевіряйте це до запуску. Експеримент 2 sizes × 2 k × reranker on/off уже має 8 конфігурацій, тому не змінюйте одночасно ще й модель та корпус.''',
['Dense + lexical','Candidate union','Cross-encoder / RRF','Deduplicate + budget'],
('Candidate generation then refinement','Перший етап оптимізує recall, другий — precision у малому контексті. Відокремлення дозволяє обмежити дорогий reranking top-N, але встановлює верхню межу якості через recall першого етапу.'),
[('Міняйте один фактор','Ablation дозволяє пояснити покращення. Повний grid може бути дорожчим, але він показує взаємодії налаштувань.'),('Вимірюйте latency','Reranker може підняти якість і порушити SLO. Порівняйте gain із p95 і RAM.'),('Оцінюйте дублі','Overlap може штучно підняти кількість hits. Рахуйте релевантність за document або evidence IDs відповідно до задачі.'),('Заморозьте test set','Налаштування робіть на dev; фінальний звіт — на відкладених питаннях. Інакше це підбір під оцінку.')],
[('Reranker лікує будь-який retrieval','Якщо evidence відсутній у candidates, його неможливо підняти. Спочатку перевірте candidate recall.'),('Порівняння сирих scores','BM25 та cosine мають різні шкали. Використовуйте rank fusion або валідуйте калібрування.'),('Overlap без межі','Створює надлишковий індекс і дублікати. Обов’язково overlap<size і перевірка diversity.')],
['Реалізуйте splitter із явним step і стабільними IDs.', 'Зберіть два списки IDs та реалізуйте RRF без дублювання в кожному списку.', 'Порівняйте candidate Recall@N і final Recall@k.', 'Додайте реальний cross-encoder у лабораторній і виміряйте додаткову latency.'],
'''На corpus із розділу 8 порівняйте два sizes, два top-k і reranking on/off. Виберіть 20 dev та 10 test питань; зафіксуйте embedding-модель. Для кожної конфігурації збережіть chunk count, Recall@k, latency і кількість повторів джерел. Ручно перевірте питання, де size змінив результат. Артефакти: config matrix, результати всіх runs і аргументований вибір. Не приховуйте конфігурації, які виявилися гіршими.''',
['Splitter покриває кінець тексту, не зациклюється та відхиляє overlap≥size.', 'RRF повертає унікальні IDs із стабільним tie-break.', 'Звіт порівнює однакові питання й містить усі запущені конфігурації.'],
['Чи контекст містить усі умови відповіді?', 'Чи якісний gain виправдовує latency?', 'Чи відсутні дублікати, що витіснили інше джерело?'],
['Чому reranker не виправить відсутнього кандидата?', 'Коли великі chunks кращі за малі?', 'Як відрізнити ефект chunking від зміни моделі?'],
[('Sentence Transformers: rerank','https://www.sbert.net/examples/sentence_transformer/applications/retrieve_rerank/README.html'),('Cross-encoder overview','https://www.sbert.net/docs/cross_encoder/usage/usage.html'),('BEIR retrieval benchmark','https://github.com/beir-cellar/beir')],
('Пошук: RAG chunking reranking ablation','https://www.youtube.com/results?search_query=RAG+chunking+reranking+ablation'))

chapter('Оцінювання AI-систем',
'Побудувати evaluation runner, який відокремлює якість retrieval, відповіді та контракту й не приймає порожній run за успіх.',
[
'''Без evaluation AI-розробка перетворюється на перегляд кількох відповідей. Хороший набір містить типові, складні й негативні запити, реальні джерела та правила оцінювання. Визначте одиницю успіху: чи потрібна точна фраза, правильний факт, коректна відмова або цитата? Для багатьох генеративних задач exact string match надто жорсткий: перефразування може бути правильним. Але для категорій, IDs і чисел він корисний. Обирайте метрику для поведінки, а не підганяйте поведінку під зручну метрику.''',
'''Розділяйте retrieval metrics, format checks і answer quality. Високий Recall@k не гарантує, що модель правильно використає evidence. Валідна схема не гарантує фактів. LLM-as-judge може швидко оцінити багато відповідей, але має position bias, preference до стилю й власні помилки. Напишіть рубрику та звірте частину judgments із людиною. Не використовуйте judge того самого pipeline як єдине джерело істини. Зберігайте prompt, модель judge і обґрунтування оцінки для аудиту.''',
'''Run має ідентифікатор, час, конфігурацію, dataset version і результати кожного прикладу. Skipped або errored не дорівнює passed. Не фільтруйте невдалі запити перед обчисленням метрики; враховуйте їх за явно описаним правилом. Порожній dataset повинен завершуватися помилкою. Порівнюйте зміни paired способом: відповіді на ті самі питання до й після. Маленький набір дає нестабільні оцінки, тому кількість прикладів і якісні спостереження мають бути поруч із відсотками.'''],
[('Golden dataset','Набір перевірених прикладів з очікуваними фактами та джерелами. Він теж може містити помилки й потребує ревізії.'),('Groundedness','Наскільки відповідь випливає з evidence. Це відрізняється від загальної фактичної правильності.'),('MRR','Середнє 1/rank першого релевантного результату. Корисне, коли важливо знайти хоча б одне джерело високо у видачі.'),('Rubric','Формальні правила ручної або judge-оцінки. «Відповідь хороша» недостатньо; визначте умови 0,1,2 балів.')],
'MRR = (1/Q) Σ_q 1/rank_first_relevant(q); відсутність relevant → 0.',
'''Для трьох питань із relevant на позиціях 1, 2 і відсутнього MRR=(1+0,5+0)/3=0,5. Recall@3 при цьому залежить від кількості всіх релевантних джерел. Якщо два з трьох API-запитів завершилися помилкою, не оцінюйте лише третій як 100% успіх. Окремо запишіть completion rate=1/3 та quality серед завершених або суворий overall pass rate. Визначте це правило до перегляду результатів, щоб не вибирати вигідну інтерпретацію.''',
['Versioned dataset','Pipeline under test','Per-case checks','Aggregate + review'],
('Evaluation as an independent consumer','Runner викликає той самий публічний контракт, що й користувач, але зберігає проміжні метадані для debug. Оцінювач не змінює відповідь перед перевіркою й не приховує exception.'),
[('Включіть no-answer','Інакше система, яка завжди генерує, може отримати високу оцінку. Перевіряйте і false refusal.'),('Проводьте ручний аудит','Випадкова вибірка та всі тяжкі помилки допомагають знайти слабкість автоматичної рубрики.'),('Зберігайте raw results','Перерахунок нової метрики не має вимагати повторного inference. Це займає диск, тому редагуйте приватні дані.'),('Порівнюйте на тих самих даних','Paired evaluation зменшує вплив випадкового складу набору. Не підміняйте dataset між runs.')],
[('Нуль тестів — зелений звіт','Empty dataset не перевірив нічого. Runner має явно відхилити його.'),('Видалення невдалих запитів','Штучно завищує якість. Позначайте failed/errored і звітуйте completion rate.'),('Один judge без аудиту','Може винагороджувати стиль замість фактів. Калібруйте на human labels.')],
['Опишіть JSONL зі question, expected_facts, relevant_ids та answerable.', 'Реалізуйте Recall@k і MRR із перевіркою входу.', 'Runner створює результат для кожного запиту, включно з exception.', 'Додайте рубрику ручної оцінки й фінальний звіт із counts, а не лише середніми.'],
'''Створіть 30 eval-питань для RAG: 20 answerable, 5 поза базою, 5 неоднозначних або adversarial. Напишіть runner для fake і реального adapter. Додайте CSV або JSON report із retrieval, schema, citations і ручною factuality. Порівняйте baseline та одну зміну з розділу 9. Позначте failed, skipped і unrun окремо. Артефакти: dataset version, runner, два звіти та розбір трьох найбільш небезпечних помилок.''',
['Порожні queries або порожній relevant set відхиляються там, де метрика потребує ground truth.', 'Відсутнє джерело дає 0, а не exception або виключення зі звіту.', 'Counts дорівнюють розміру dataset; результати належать поточному run.'],
['Чи рубрика перевіряє факти, а не красномовність?', 'Чи були reviewed тяжкі помилки?', 'Чи оцінюється відмова як окрема поведінка?'],
['Чим MRR відрізняється від Recall@k?', 'Чому quality серед успішних не дорівнює overall reliability?', 'Який bias може мати LLM-as-judge?'],
[('pytest: getting started','https://docs.pytest.org/en/stable/getting-started.html'),('NIST AI RMF','https://www.nist.gov/itl/ai-risk-management-framework'),('Ragas: documentation','https://docs.ragas.io/en/stable/')],
('Пошук: LLM evaluation groundedness human rubric','https://www.youtube.com/results?search_query=LLM+evaluation+groundedness+human+rubric'))

chapter('Tools та контрольовані агенти',
'Реалізувати bounded tool loop, перевіряти дозволи та аргументи до виконання й не виконувати довільний код моделі.',
[
'''Агент — система, де модель може пропонувати наступну дію, отримати результат і продовжити. Не кожен workflow потребує агента. Якщо послідовність «пошук → відповідь» відома, звичайний pipeline простіший і легше тестується. Агент корисний, коли потрібно обрати з кількох дозволених операцій залежно від проміжного результату. Ціна — додаткові виклики, складніший debug і ризик циклів. Почніть із двох read-only tools і мінімальної кількості кроків.''',
'''Tool call від моделі — пропозиція, а не дозвіл. Сервер перевіряє назву, schema аргументів, права користувача, бюджет і безпечність операції. Registry має містити тільки дозволені callable. Не робіть getattr за довільним рядком, eval чи shell execution. Tool output також недовірений: вебсторінка може містити prompt injection. Передавайте моделі лише необхідні дані та не дозволяйте output змінити policy. Для дій із побічними ефектами додавайте явне підтвердження конкретних аргументів.''',
'''Loop має умови завершення: фінальна відповідь, step limit, token budget, deadline або помилка. Повтор одного tool call може бути ознакою зациклення; fingerprint виклику допомагає помітити це. Зберігайте trajectory: назва tool, валідовані args, status і час, але не секрети. Agent success оцінюйте за досягненням задачі, а не за кількістю успішних API-викликів. Можна мати ідеальний tool log і неправильну фінальну відповідь.'''],
[('Tool schema','Формат аргументів та результату. Він допомагає моделі запропонувати виклик, але перевірка залишається у сервері.'),('Allowlist','Явний набір дозволених tools. Усе інше відхиляється за замовчуванням.'),('Trajectory','Послідовність рішень, викликів і результатів. Це основа debug та evaluation агентів.'),('Human-in-the-loop','Людина підтверджує конкретну дію. Загальна згода «використовуй tools» не має автоматично дозволяти платіж чи видалення.')],
'Max tool calls ≤ step_limit; worst-case cost ≈ ΣLLM calls + Σtool costs.',
'''Якщо loop дозволяє 5 кроків, кожен може містити LLM-виклик і пошук, бюджет не дорівнює вартості одного запиту. За 2 секунд LLM і 0,3 секунди tool можливий час понад 11,5 секунди без retries. Для паралельних незалежних tools latency зменшується, але concurrency і навантаження зростають. Ліміт кроків захищає ресурси, однак іноді зупиняє корисну задачу; повертайте пояснення, а не мовчазно урізану відповідь.''',
['LLM proposed call','Schema + authorization','Allowlisted tool','Result → bounded loop'],
('Command dispatcher with policy gate','Registry з’єднує назву з функцією; gate перевіряє аргументи і права перед виконанням. Планування не може обійти gate. Окремий read-only режим спрощує перший реліз і зменшує ризик побічних ефектів.'),
[('Почніть із read-only','Пошук і простий калькулятор достатні для навчання. Write tools потребують audit та підтвердження.'),('Обмежуйте кроки','Step budget простий і перевірюваний. Додайте deadline, бо один завислий tool все одно може блокувати loop.'),('Валідуйте аргументи','Число має бути скінченним; query має мати ліміт. JSON від моделі не є довіреним.'),('Зберігайте trace','Без trajectory складно зрозуміти, де агент помилився. Редагуйте чутливі аргументи.')],
[('eval як калькулятор','Виконає довільний код. Використайте дозволені операції або обмежений AST parser.'),('Довільні tools із назви','getattr може відкрити небезпечну функцію. Тільки allowlisted registry.'),('Нескінченний self-correction','Модель може повторювати неправильну дію. Зупиняйте loop і повідомляйте про ліміт.')],
['Створіть registry add/search із фіксованими схемами.', 'Перевірте tool name, набір ключів, типи та скінченність значень.', 'Реалізуйте dispatch і bounded sequence без LLM.', 'У лабораторній додайте model planner; збережіть той самий dispatcher як єдину точку виконання.'],
'''Побудуйте агента з пошуком документів та калькулятором лише з add і multiply. Дайте 10 задач, частина з яких не потребує tools, а частина провокує unknown tool чи повтор. Максимум 5 кроків і загальний deadline. Підготуйте manual approval flow для уявної write-дії, але не підключайте її до реального зовнішнього сервісу. Артефакти: registry, policy tests, trajectories і оцінка task success.''',
['Unknown tool та зайві аргументи відхиляються до виконання.', 'NaN, infinity і bool замість number не приймаються.', 'Послідовність понад step limit не виконується.'],
['Чи tools потрібні для задачі, а не додані заради моди?', 'Чи користувач бачить, що саме підтверджує?', 'Чи tool output не змінює policy?'],
['Чим pipeline відрізняється від agent loop?', 'Чому успішний tool call не доводить task success?', 'Який ліміт захищає від зависання одного tool?'],
[('Hugging Face: agents','https://huggingface.co/learn/agents-course/unit1/what-are-agents'),('Python: ast','https://docs.python.org/3/library/ast.html'),('OWASP agentic AI','https://genai.owasp.org/')],
('Пошук: Hugging Face agents course tools','https://www.youtube.com/results?search_query=Hugging+Face+agents+course+tools'))

chapter('Пам’ять і багатокористувацький діалог',
'Зберігати історію ізоляційно, будувати контекст за бюджетом і не плутати повідомлення користувача з системною політикою.',
[
'''Пам’ять діалогу — це дані, які ваш застосунок передає у наступний запит. Модель сама не має доступу до SQLite і не пам’ятає попередній HTTP-виклик. Короткочасна пам’ять містить останні повідомлення, довгострокова може зберігати профіль або знайдені факти. Чітко визначте, що можна зберігати, на який строк і як видаляти. Не накопичуйте приватні дані лише тому, що вони можуть колись знадобитися. Видалення розмови має прибирати також summaries, embeddings і кеші, які з неї походять.''',
'''Ізоляція визначається серверною особою користувача та session ID. Кожен запит до messages повинен перевіряти user_id; session ID без owner недостатній. Використовуйте параметризований SQL. Не приймайте user_id як довірений параметр клієнта. Зберігайте роль і порядок повідомлень; user не повинен створювати role=system. У контексті система визначає policy, а історія — предмет розмови. Старий tool output не стає авторитетною інструкцією лише тому, що потрапив у memory.''',
'''Повна історія швидко переповнює window. Sliding window проста, але може втратити ранню вимогу. Summary економить токени, але є генеративним перетворенням і може спотворити факт. Зберігайте оригінал, версію summary та посилання на повідомлення. Hybrid memory поєднує останні turns, summary і retrieval релевантних фактів; це покращує покриття ціною складності. Підбирайте стратегію на діалогових тестах, де важливий факт з’являється на початку й потрібен наприкінці.'''],
[('Turn','Пара користувацької репліки та відповіді. Обрізання між ними може створити дивний контекст.'),('Session isolation','Дані однієї розмови й власника не мають потрапляти іншому. ID має сенс лише разом з авторизацією.'),('Summary drift','Поступове спотворення фактів під час повторного підсумовування. Перевіряйте summary на ground truth.'),('Retention','Правило строку зберігання й видалення. Воно поширюється на похідні дані, а не лише таблицю messages.')],
'History tokens ≤ window − system − retrieval − question − output reserve.',
'''Для window=8000, system=500, retrieval=3000, question=200 і reserve=1000 історії лишається 3300. Якщо кожен turn коштує близько 600 токенів, поміститься приблизно 5 turns, а не весь місяць розмов. Це лише оцінка: токени рахуються tokenizer моделі. Лабораторний baseline використовує умовну ціну слів, щоб протестувати порядок і budget, але у реальній інтеграції замініть її точним counting.''',
['Authenticated user','User + session messages','Window / summary','Budgeted LLM context'],
('Memory repository + context policy','Repository забезпечує ізоляційне зберігання; context policy вирішує, які записи передати моделі. Це різні відповідальності: скорочення контексту не повинно видаляти оригінальну історію.'),
[('Ставте owner у кожен query','Це захищає навіть якщо session ID вгадали або скопіювали. Перевірка лише на UI недостатня.'),('Зберігайте оригінал','Summary — похідний артефакт. Його можна перегенерувати, якщо модель або рубрика змінилися.'),('Рахуйте токени перед викликом','Краще керовано скоротити історію, ніж отримати context overflow.'),('Окремо зберігайте policy','Не дозволяйте історії додавати system role. Це трохи обмежує гнучкість, але захищає межу довіри.')],
[('Спільний global list','Користувачі бачать чужі повідомлення, особливо під concurrency. Потрібен owner-scoped repository.'),('Вічне summary of summary','Помилки накопичуються. Періодично підсумовуйте з оригіналів і перевіряйте факти.'),('LIMIT без ORDER BY','Порядок рядків не гарантований. Явно сортуйте за sequence або timestamp+ID.')],
['Створіть messages з owner, session, seq, role та text.', 'Append приймає лише user/assistant і параметризований SQL.', 'Read відбирає за owner+session та явним seq.', 'Context builder бере останні повні повідомлення у межах бюджету, не змінюючи збережені дані.'],
'''Проведіть два паралельні діалоги різних користувачів з однаковим session ID. Додайте факт на початку, 10 сторонніх turns і питання про ранній факт. Порівняйте sliding window та summary. Виміряйте токени, factuality та кількість пропущених умов. Реалізуйте видалення session і перевірте похідні summaries. Артефакти: schema, isolation tests, діалоговий eval і retention policy.''',
['Однакові session IDs різних owner не змішують історії.', 'Повідомлення повертаються у стабільному порядку.', 'Budgeted context не перевищує бюджет; oversize message має явну політику.'],
['Чи збереглося раннє важливе обмеження?', 'Чи summary не додав нових фактів?', 'Чи користувач може видалити пам’ять?'],
['Чому session ID не є авторизацією?', 'Що втрачає sliding window?', 'Чи summary можна вважати джерелом істини?'],
[('Python: sqlite3','https://docs.python.org/3/library/sqlite3.html'),('OWASP: authorization','https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html'),('Transformers: chat templates','https://huggingface.co/docs/transformers/chat_templating')],
('Пошук: LLM conversation memory context window summary','https://www.youtube.com/results?search_query=LLM+conversation+memory+context+window+summary'))

chapter('Локальні моделі та ресурси inference',
'Оцінити пам’ять і швидкість локальної моделі, безпечно підняти inference server та порівняти якість із API.',
[
'''Локальна модель переносить обчислення й операційну відповідальність на вашу машину. Вона може допомогти з приватністю та незалежністю від провайдера, але «без API» не означає «без витрат». Потрібні RAM або VRAM, диск, електроенергія, час завантаження та підтримка. Модель із відкритими вагами не обов’язково має необмежену ліцензію. Перед запуском прочитайте model card і ліцензію, зафіксуйте revision та джерело артефакту. Не запускайте download scripts із невідомого дзеркала лише заради меншого файла.''',
'''Квантизація зменшує число бітів на вагу. 4-bit представлення економить пам’ять порівняно з FP16, але додає scales, metadata та можливу втрату якості. Назва Q4 не означає рівно 0,5 byte на весь параметр у реальному файлі. KV cache залежить від context і concurrency, а activations та runtime мають додатковий overhead. Модель може завантажитися й потім отримати OOM на довгому запиті. Плануйте ресурси під одночасні запити, а не лише idle server.''',
'''Latency має кілька складових: час до першого токена, prefill і швидкість decode. Tokens per second не описує повний досвід користувача. Batch може підняти throughput, але збільшити очікування окремого запиту. На CPU мала quantized instruct-модель часто зручніша для навчання, ніж велика модель, яка ледве поміщається. Не відкривайте inference port у публічний інтернет без auth і лімітів. Локальний сервер слухає loopback; зовнішній доступ проходить через захищений застосунок.'''],
[('Quantization','Наближене представлення чисел меншою кількістю бітів. Компроміс між розміром, швидкістю й помилкою залежить від kernels і hardware.'),('TTFT','Time to first token: очікування першого видимого результату, включно з чергою та prefill.'),('Throughput','Обсяг обробки за одиницю часу. Високий aggregate throughput не гарантує низький latency одному користувачу.'),('GGUF','Формат моделей і metadata для екосистеми llama.cpp. Сумісність tokenizer і chat template все одно треба перевірити.')],
'Weight memory lower bound ≈ parameters × bits / 8; total = weights + KV + activations + runtime.',
'''Для 1 млрд параметрів у 4-bit нижня арифметична оцінка ваг — 0,5 GB, у FP16 — 2 GB. Реальний обсяг більший через metadata та runtime. Якщо доступно 4 GB, не можна автоматично зробити висновок, що FP16-модель із великим контекстом працюватиме. Залиште headroom і виміряйте peak memory на довгому prompt та максимальній concurrency. Навчальний приклад рахує лише нижню межу й навмисно не стверджує готовність hardware.''',
['Verified model file','Local inference server','Authenticated API adapter','Measured output'],
('Local provider behind the same port','Ваш бізнес-код використовує той самий Provider інтерфейс, що й для хмарного API. Змінюється adapter та конфігурація, а не retrieval. Це дозволяє paired comparison моделей на однаковому eval-наборі.'),
[('Почніть із малої моделі','Швидкі ітерації важливіші за максимальну кількість параметрів. Потім масштабування можна обґрунтувати eval.'),('Перевіряйте артефакти','Використовуйте офіційне джерело й checksum якщо наданий. Не вимикайте TLS або trust checks заради запуску.'),('Тестуйте довгий prompt','Idle RAM недостатня. Peak memory залежить від context і batch.'),('Вимірюйте end-to-end','Окремо TTFT, decode speed і total latency. Користувачу важлива відповідь, а не лише benchmark kernels.')],
[('Модель помістилася — готово','OOM може статися під навантаженням. Потрібен тест worst-case context.'),('Публічний port без auth','Будь-хто може витрачати ресурси й отримати доступ до контексту. Використовуйте loopback і захищений proxy.'),('4-bit завжди краще','Стиснення може знизити якість або бути повільнішим на певному hardware. Порівнюйте власні дані.')],
['Розрахуйте нижню межу пам’яті й перевірте доступні ресурси.', 'Завантажте сумісний instruct GGUF з перевіреного джерела; зафіксуйте revision.', 'Запустіть llama-server на 127.0.0.1 і перевірте реальний generation request.', 'Підключіть local adapter і повторіть eval API-моделі на тих самих питаннях.'],
'''Виберіть модель, яка вкладається у RAM із запасом. Якщо hardware не дозволяє inference, виконайте sizing і позначте live-перевірку як unrun, а не passed. За доступних ресурсів виміряйте 10 коротких і 5 довгих запитів: TTFT, total latency, tokens/s, RAM та factuality. Порівняйте дві quantization-конфігурації за можливості. Артефакти: model manifest, команда запуску, результати й опис обмежень.''',
['Sizing function відхиляє непозитивні parameters/bits і рахує bytes без прихованого округлення.', 'Live readiness означає representative generation, а не лише відкритий port.', 'Eval позначає unrun inference явно за відсутності hardware.'],
['Чи ліцензія дозволяє обраний сценарій?', 'Чи пікова пам’ять виміряна, а не тільки оцінена?', 'Чи якість на українських питаннях достатня?'],
['Чому weights не дорівнюють усій пам’яті?', 'Що втрачає метрика tokens/s без TTFT?', 'Чи локальний deployment автоматично приватний?'],
[('llama.cpp','https://github.com/ggml-org/llama.cpp'),('Ollama documentation','https://docs.ollama.com/'),('Hugging Face: model cards','https://huggingface.co/docs/hub/model-cards')],
('Пошук: llama.cpp quantization local inference benchmark','https://www.youtube.com/results?search_query=llama.cpp+quantization+local+inference+benchmark'))

chapter('Безпека й observability',
'Визначити межі довіри, перевірити доступ до evidence й додати метрики без витоку приватних даних.',
[
'''AI-система додає нові поверхні атаки, але не скасовує звичайну безпеку вебзастосунку. Авторизація, parameterized SQL, обмеження body, секрети та ізоляція tenant усе ще критичні. Prompt injection відрізняється від класичної ін’єкції тим, що зловмисний текст намагається змінити поведінку моделі через її мовний інтерфейс. Він може бути в question, документі або tool output. Не можна гарантувати захист одним системним реченням. Потрібні обмежені можливості, детерміновані policy checks і мінімальні привілеї.''',
'''Threat model починається з активів і меж довіри: приватні документи, ключ провайдера, історії, tools та compute budget. Намалюйте, звідки приходять дані і хто може їх змінити. Навіть відповідь моделі недовірена, якщо ви відображаєте її як HTML або використовуєте у запиті. Escape текст, перевіряйте URLs і не запускайте SQL чи код. Права перевіряйте до retrieval; видалення forbidden source після generation не прибере факт, який уже потрапив у відповідь.''',
'''Observability складається з logs, metrics і traces. Request ID з’єднує HTTP, retrieval і generation; метрики показують частоти та розподіли, а trace — конкретний шлях. Не використовуйте question або user ID як необмежені metric labels: cardinality може перевантажити систему та розкрити дані. Вимірюйте latency, error rate, refusal rate, token usage і retrieval count. Redaction зменшує діагностичність, але це компроміс на користь приватності; за потреби створіть окремий захищений audit, а не публічні логи.'''],
[('Trust boundary','Межа між контрольованими компонентами та недовіреним входом. Дані після LLM не стають довіреними автоматично.'),('Least privilege','Компонент має лише необхідні права. Read-only tool не повинен мати credentials для видалення.'),('Cardinality','Кількість різних значень label у метриках. Висока cardinality збільшує пам’ять і витрати.'),('Redaction','Вилучення чутливих даних із logs і traces. Regex недостатньо для всіх секретів; краще не логувати їх узагалі.')],
'Error rate = failed requests / total requests; p95 = latency, нижче якої лежить 95% вибірки.',
'''Для 100 запитів і 7 технічних failures error rate=7%. Контрольована відмова за відсутності evidence не обов’язково технічна помилка: задайте окремий status. Інакше оптимізація error rate змусить систему відповідати там, де вона має відмовитися. Якщо p95 latency=4 секунди, приблизно 5% запитів повільніші; це нічого не каже про тяжкість помилок. Додайте окремий alert на доступ до чужого source, навіть якщо він стався один раз.''',
['Untrusted input','Auth + size policy','Authorized retrieval','Escaped output + trace'],
('Defense in depth','Незалежні перевірки входу, retrieval, tools і rendering зменшують наслідки одного провалу. Вони не повинні покладатися на ту саму генеративну оцінку. Для critical actions є окремий deterministic policy gate.'),
[('Перевіряйте ACL до ranking','Forbidden documents не повинні потрапити у context. Це сильніше за UI-фільтрацію.'),('Логуйте метадані','Request ID, duration і status часто достатні. Повний prompt зручний, але небезпечний.'),('Обмежуйте ресурси','Body size, concurrency і deadline захищають від resource exhaustion. Надто малі ліміти можуть шкодити легітимним запитам — вимірюйте.'),('Тестуйте adversarial corpus','Перевірте injection, чужий tenant, HTML і довгі payload. Успіх одного тесту не означає повний захист.')],
[('System prompt як firewall','Модель може порушити інструкцію. Потрібні зовнішні policy checks.'),('Секрет у context','Навіть корисна модель може повторити його у відповіді. Не передавайте ключі взагалі.'),('Текст LLM як HTML','Створює XSS-ризик. Відображайте як text або використовуйте перевірений sanitizer.')],
['Опишіть assets і trust boundaries на схемі.', 'Створіть authorize_chunks() із owner-scoped фільтрацією.', 'Валідуйте question size та request ID; не log raw body.', 'Додайте adversarial тести й audit статусів без секретних значень.'],
'''Створіть 10 adversarial сценаріїв: injection у документі, чужий tenant, великий body, unknown tool, HTML у відповіді та спроба витягти ключ. Запустіть їх на pipeline й запишіть expected/actual. Додайте request ID і timings для retrieval/generation. Перегляньте логи вручну на секрети й персональні дані. Артефакти: threat model, test corpus, sanitization policy і dashboard або JSON-звіт метрик.''',
['Forbidden tenant IDs не повертаються з authorize_chunks.', 'Порожні й oversize questions відхиляються до expensive inference.', 'HTML-подібний текст відображається як текст; logs не містять token.'],
['Чи policy працює без довіри до моделі?', 'Чи помилка не розкриває credentials або path?', 'Чи метрики не змішують refusal з technical failure?'],
['Чому redaction слабша за мінімізацію даних?', 'Що таке indirect prompt injection?', 'Чому post-generation ACL недостатня?'],
[('OWASP LLM Top 10','https://genai.owasp.org/llm-top-10/'),('OWASP logging','https://cheatsheetseries.owasp.org/cheatsheets/Logging_Cheat_Sheet.html'),('OpenTelemetry: concepts','https://opentelemetry.io/docs/concepts/')],
('Пошук: OWASP LLM prompt injection defense observability','https://www.youtube.com/results?search_query=OWASP+LLM+prompt+injection+defense+observability'))

chapter('Деплой, навантаження та продуктивність',
'Підготувати повторюваний deployment, перевірити persistence і виміряти p50/p95 разом із частотою помилок.',
[
'''Deployment — відтворення перевіреного середовища, а не просто відкриття порту. Зафіксуйте залежності, runtime, command, variables та storage paths. Контейнер має бути immutable; користувацькі дані зберігаються у persistent volume або зовнішній БД. Якщо SQLite лежить у файловій системі контейнера, rebuild може стерти її. Snapshot не замінює резервну копію та перевірку restore. На безкоштовних хостингах враховуйте sleep: серверні нагадування не працюватимуть під час простою.''',
'''Liveness відповідає, чи процес живий; readiness — чи може обслуговувати запит. Healthcheck не повинен щоразу викликати платний LLM: це створить витрати й зайву залежність. Репрезентативний smoke test запускається окремо та перевіряє справжню поведінку. Multiple workers збільшують throughput, але in-memory state між ними не спільний, а фоновий scheduler може стартувати кілька разів. Для SQLite враховуйте один writer і locks; для більшого навантаження зовнішня БД може бути кращою.''',
'''Load test повинен перевіряти реалістичний mix запитів, а не лише /health. Warm-up, cold start, довгі inputs і failures впливають на distribution. Closed-loop тест, де клієнт чекає попередню відповідь, може приховати чергу під навантаженням. Вимірюйте arrivals, completion rate, concurrency, latency й resources. Оптимізація caching зменшує latency, але ключ має включати model/prompt/index version і tenant; інакше кеш поверне застарілу чи чужу відповідь.'''],
[('p50 / p95','Медіана й хвостовий percentile latency. Визначте спосіб обчислення та кількість samples.'),('Persistent volume','Диск, який не зникає разом із контейнером. Його наявність треба перевірити restart/restore тестом.'),('Readiness','Здатність обслуговувати роботу зараз. Порт, який слухає, не доводить готовність залежностей.'),('Cache invalidation','Скидання результату після зміни моделі, промпту, прав чи індексу. Неповний key небезпечніший за повільний запит.')],
'Little’s law: L = λW у стабільній системі; nearest-rank p = sorted[ceil(p×N)−1].',
'''За 2 запити/с і середньої тривалості 3 секунди в стабільній системі очікується близько 6 запитів у роботі або черзі. Це не рекомендація встановити semaphore=6 без інших перевірок: traffic burst і tail latency можуть вимагати іншого budget. Для 20 samples nearest-rank p95 — 19-й елемент відсортованого списку. Вкажіть convention у звіті, бо interpolated percentile може відрізнятися на малих наборах.''',
['HTTPS ingress','Workers + limits','Persistent DB / index','Metrics + backups'],
('Stateless API, explicit state','HTTP-workers не зберігають важливий state у global lists. БД та індекс мають явні volumes, а scheduler — один owner або окремий процес. Це полегшує restart і горизонтальне масштабування.'),
[('Перевіряйте restore','Створіть запис, зробіть backup, відновіть у новому path і прочитайте. Файл backup без тесту ще не гарантує відновлення.'),('Фіксуйте versions','Зміна dependency під час build може зламати поведінку. Lock або повні pins підвищують повторюваність.'),('Додавайте timeout і limits','Навантаження без bounds накопичує чергу. Reject може бути кращим за нескінченне очікування.'),('Рахуйте failures','Latency лише успішних запитів може виглядати чудово при масових timeout. Звітуйте completion rate поруч.')],
[('Дані в image layer','Rebuild прибирає результати. Використайте volume і backup.'),('Кілька scheduler workers','Нагадування дублюються. Визначте single owner або shared locking.'),('Load test тільки /health','Не перевіряє retrieval та generation. Потрібні representative requests.')],
['Створіть Dockerfile з non-root користувачем і pinned dependencies.', 'Налаштуйте data volume й одну команду старту.', 'Реалізуйте health та representative smoke test окремо.', 'Зберіть latency samples і порахуйте percentiles разом із error rate.'],
'''Контейнеризуйте фінальний API. Додайте persistent storage, створіть користувача/запис, перезапустіть контейнер і перевірте дані. Виконайте 100 representative requests із concurrency=10 на fake, потім окремий контрольований live-run якщо є квота. Виміряйте cold start, p50/p95, failures і RAM. Зробіть backup та restore у новий каталог. Артефакти: Dockerfile, команда запуску, load script, report та recovery guide.''',
['Percentile function відхиляє порожній набір і невалідні значення.', 'Restart зберігає state; restore читає очікувані записи.', 'Smoke перевіряє /ask, а report містить failures і sample count.'],
['Чи hosting sleep сумісний із нагадуваннями?', 'Чи cache key містить tenant і versions?', 'Чи deployment відтворюється без ручних секретів у коді?'],
['Чим readiness відрізняється від liveness?', 'Чому average latency приховує проблеми?', 'Який state не можна залишати у worker memory?'],
[('FastAPI: Docker','https://fastapi.tiangolo.com/deployment/docker/'),('Docker: storage','https://docs.docker.com/engine/storage/volumes/'),('SQLite: online backup','https://www.sqlite.org/backup.html')],
('Пошук: FastAPI Docker load testing persistent volume','https://www.youtube.com/results?search_query=FastAPI+Docker+load+testing+persistent+volume'))

chapter('Фінальний проєкт: доказова готовність',
'Зібрати асистента з retrieval, джерелами, ізоляцією, оцінюванням і повторюваним запуском та представити чесний release report.',
[
'''Фінальний проєкт об’єднує компоненти, але його головний результат — доказ, що система виконує обраний контракт. Оберіть вузьку базу знань і конкретного користувача. Асистент для інструкцій одного продукту легше оцінюється, ніж «відповідає на все». Визначте answerable scope, права доступу та поведінку за браку даних. Архітектура має показувати ingest, query, auth, storage, model adapter і evaluation. Не додавайте agents, якщо простий RAG уже вирішує задачу: складність має мати вимірювану причину.''',
'''Release report містить версії корпусу, індексу, моделі й промпту, кількість eval-питань, quality metrics, latency і відомі failures. Нуль критичних витоків на тестовому corpus — необхідна умова, але не доказ абсолютної безпеки. Gate перевіряє конкретні вимірювання, а не оптимістичні припущення. Порогові значення обирайте відповідно до ризику й задачі до фінального run. Якщо threshold підібрано після результатів, це демонстрація, а не незалежна перевірка.''',
'''Демо має включати успішний запит, відмову, failure залежності та відновлення після restart. Покажіть source link і перевірте його вручну. README має дозволити іншому розробнику відтворити середовище, додати документи, запустити тести й зрозуміти, які перевірки потребують credentials. Secrets вводяться через environment, а не у приклад коду. Backup і deletion policy завершують lifecycle даних. Після release продовжуйте збирати помилки й періодично переглядати eval-набір, не перетворюючи його на єдину ціль оптимізації.'''],
[('Acceptance gate','Явні умови release: quality, completion, latency і critical safety tests. Gate не повинен приховувати unrun перевірки.'),('Reproducibility manifest','Версії й конфігурація, потрібні для повторення run. Без них відсотки у презентації не мають стабільного змісту.'),('Known limitations','Підтверджені межі системи: unsupported мови, stale data, hardware limits, характерні помилки. Це частина продуктового контракту.'),('Release evidence','Звіти та артефакти конкретної перевірки. Скрипт, який ніколи не запускали, не є доказом.')],
'Release = quality_pass ∧ safety_pass ∧ reliability_pass ∧ reproducibility_pass.',
'''Умовний навчальний gate може вимагати не менше 30 eval-питань, Recall@3≥0,8, нуль tenant leaks і p95≤5 секунд. Це демонстраційні пороги, не production-рекомендація. Навіть якщо recall=0,9, один critical leak блокує release. Якщо p95 не виміряний, значення unknown не має перетворюватися на pass. Звіт gate повинен повертати список причин, щоб команда розуміла, що саме потрібно виправити або перевірити.''',
['Versioned corpus','Auth + RAG API','Eval + safety gates','Release + recovery'],
('Evidence-driven release','Build створює артефакт; evaluation і smoke перевіряють його конкретну версію; release gate читає звіти. Після зміни моделі або індексу evidence потрібно оновити, а не переносити зелені результати від старого build.'),
[('Зменшіть scope','Вузький проєкт із сильними доказами корисніший за багато неперевірених функцій.'),('Покажіть відмову','Негативне демо демонструє межі. Користувач краще розуміє, коли довіряти системі.'),('Перевірте чистий запуск','Новий каталог або container має працювати за README. Це виявляє приховані ручні кроки.'),('Випустіть failure report','Список помилок допомагає планувати наступні зміни; приховування їх створює хибну готовність.')],
[('Demo cherry-picking','Лише три вдалі питання приховують ненадійність. Потрібен повний eval report.'),('Release без provenance','Невідомо, що саме перевірено. Зберігайте commit і versions.'),('Optional як required pass','Незапущений live inference не доводить якість. Розділіть passed, failed та unrun.')],
['З’єднайте компоненти попередніх модулів через стабільні інтерфейси.', 'Створіть release manifest і policy thresholds.', 'Реалізуйте gate, який повертає всі причини відмови.', 'Виконайте clean-start, evaluation, security та backup/restore, потім підготуйте demo.'],
'''Побудуйте персонального асистента документації з 10–20 файлами. Обов’язкові функції: auth, owner-scoped retrieval, citations, no-answer, bounded provider calls, persistence і eval на 30 питаннях. Опціонально додайте local model або read-only agent і покажіть його користь окремим експериментом. Підготуйте README, architecture diagram, release report і 5-хвилинне демо із негативним сценарієм. Виконайте peer review за рубрикою нижче та зафіксуйте ще не перевірені можливості.''',
['Gate відхиляє недостатній sample count, missing metrics і tenant leaks.', 'Clean-start smoke, schema tests та owner isolation виконані на поточній версії.', 'Report містить passed/failed/unrun та посилання на артефакти.'],
['Користувач може перевірити джерело кожного важливого факту.', 'Інший розробник відтворює запуск і restore за README.', 'Демо показує відмову та відомі обмеження без приховування помилок.'],
['Який failure повинен блокувати release незалежно від середньої якості?', 'Коли треба переоцінити систему після зміни?', 'Що відрізняє feature list від release evidence?'],
[('Hugging Face: agents final project','https://huggingface.co/learn/agents-course/unit4/introduction'),('NIST AI RMF','https://www.nist.gov/itl/ai-risk-management-framework'),('FastAPI: deployment concepts','https://fastapi.tiangolo.com/deployment/concepts/')],
('Пошук: end to end RAG project evaluation deployment','https://www.youtube.com/results?search_query=end+to+end+RAG+project+evaluation+deployment'))
